SELECT jsonb_build_object('campaigns',(SELECT jsonb_agg(jsonb_build_object('id',id,'codigo',codigo,'status',status,'version',version,'produto_id',produto_id,'beneficio',beneficio_percentual)) FROM estudo.campanhas),'products',(SELECT jsonb_agg(jsonb_build_object('id',id,'codigo',codigo,'status',status,'publicacao',publicacao_id)) FROM estudo.produtos),'profiles',(SELECT count(*) FROM public.tb_conta_perfis_publicos WHERE origem='ABRACEO'),'voucher_counts',(SELECT count(*) FROM estudo.vouchers),'first_access_exists',to_regclass('estudo.primeiro_acesso_empresas')::text)::text payload
